tool_calls:
awk '
BEGIN { total=0; passed=0; failed=0; }
/^PASS/ { passed++; total++; }
/^FAIL/ { failed++; total++; failures[failed] = $2; }
END {
    print "# Test Summary\n";
    print "Total: " total " | Passed: " passed " | Failed: " failed "\n";
    print "## Failures\n";
    for (i=1; i<=failed; i++) {
        print "- " failures[i];
    }
}' /data/test-results.txt

awk '
BEGIN { total=0; passed=0; failed=0; }
$1 == "PASS" { passed++; total++; }
$1 == "FAIL" { failed++; total++; failures[failed] = $2; }
END {
    print "# Test Summary\n";
    print "Total: " total " | Passed: " passed " | Failed: " failed "\n";
    print "## Failures";
    for (i=1; i<=failed; i++) {
        print "- " failures[i];
    }
}' /data/test-results.txt > /reports/test-summary.md
cat /reports/test-summary.md

